TransactionImportCSVLinesView = {
    init: async function(app, container, transaction) {
        app = app || session.app;
        container = container || $(".component[name=TransactionImportCSVLinesView]");

        var splits = ['CreatedBy', 'PayRef'];

        TransactionImportCSVLinesView.buildFieldView(container, splits.length);
        TransactionImportCSVLinesView.populateFieldView(container, transaction, splits);
    },

    buildFieldView: function(container, columns) {
        var columnTemplate = $('[name=column-template]', container).html();

        for(var i = 0; i <= columns; i++) {
            $('[name=fields-container]', container).append(columnTemplate.replace('{split}', i));
        }
    },

    populateFieldView: function(container, transaction, splits) {
        var fields = [
            {
                field: "Id",
                title: "[resource_shortdisplayname[Id]]",
                description: "[resource_description[Id]]"
            },
            {
                field: "RootBucketId",
                title: "[resource_shortdisplayname[RootBucketId]]",
                description: "[resource_description[RootBucketId]]"
            },
            {
                field: "TransactionId",
                template: function (data) { return "" + ((data.TransactionId) ? ('<a href="/Transactions/' + data.TransactionType + '?Id=' + data.TransactionId + '">' + data.TransactionId + '</a>') : '') + ""; },
                title: "[resource_shortdisplayname[TransactionId]]",
                description: "[resource_description[TransactionId]]"
            },
            {
                field: "TransactionType",
                title: "[resource_shortdisplayname[TransactionType]]",
                description: "[resource_description[TransactionType]]"
            },
            {
                field: "SourceSystemId",
                title: "[resource_shortdisplayname[SourceSystemId]]",
                description: "[resource_description[SourceSystemId]]"
            },
            {
                field: "ReferenceSeperator",
                title: "[resource_shortdisplayname[ReferenceSeperator]]",
                description: "[resource_description[ReferenceSeperator]]"
            },
            {
                field: "FileName",
                title: "[resource_shortdisplayname[FileName]]",
                description: "[resource_description[FileName]]"
            },
            {
                field: "State",
                title: "[resource_shortdisplayname[State]]",
                description: "[resource_description[State]]"
            },
            {
                field: "FailureMessage",
                title: "[resource_shortdisplayname[FailureMessage]]",
                description: "[resource_description[FailureMessage]]"
            },
            {
                field: "CreatedBy",
                title: "[resource_shortdisplayname[CreatedBy]]",
                description: "[resource_description[CreatedBy]]"
            },
            {
                field: "Reference",
                title: "[resource_shortdisplayname[Reference]]",
                description: "[resource_description[Reference]]"
            },
            {
                field: "CreditorTransactionRef",
                title: "[resource_shortdisplayname[CreditorTransactionRef]]",
                description: "[resource_description[CreditorTransactionRef]]"
            },
            {
                field: "DebtorRef",
                title: "[resource_shortdisplayname[DebtorRef]]",
                description: "[resource_description[DebtorRef]]"
            },
            {
                field: "CreditorRef",
                title: "[resource_shortdisplayname[CreditorRef]]",
                description: "[resource_description[CreditorRef]]"
            },
            {
                field: "VATRef",
                title: "[resource_shortdisplayname[VATRef]]",
                description: "[resource_description[VATRef]]"
            },
            {
                field: "Currency",
                title: "[resource_shortdisplayname[Currency]]",
                description: "[resource_description[Currency]]"
            },
            {
                field: "DocDate",
                type: "date",
                format: type.dateFormat,
                title: "[resource_shortdisplayname[DocDate]]",
                description: "[resource_description[DocDate]]"
            },
            {
                field: "DueDate",
                type: "date",
                format: type.dateFormat,
                title: "[resource_shortdisplayname[DueDate]]",
                description: "[resource_description[DueDate]]"
            },
            {
                field: "PaymentDate",
                type: "date",
                format: type.dateFormat,
                title: "[resource_shortdisplayname[PaymentDate]]",
                description: "[resource_description[PaymentDate]]"
            },
            {
                field: "RelatedTransactionRef",
                title: "[resource_shortdisplayname[RelatedTransactionRef]]",
                description: "[resource_description[RelatedTransactionRef]]"
            },
            {
                field: "PayRef",
                title: "[resource_shortdisplayname[PayRef]]",
                description: "[resource_description[PayRef]]"
            },
            {
                field: "Value",
                type: "number",
                format: type.moneyFormat,
                title: "[resource_shortdisplayname[Value]]",
                description: "[resource_description[Value]]"
            },
            {
                field: "GrossValue",
                type: "number",
                format: type.moneyFormat,
                title: "[resource_shortdisplayname[GrossValue]]",
                description: "[resource_description[GrossValue]]"
            },
            {
                field: "TaxValue",
                type: "number",
                format: type.moneyFormat,
                title: "[resource_shortdisplayname[TaxValue]]",
                description: "[resource_description[TaxValue]]"
            },
            {
                field: "IsFundable",
                type: "boolean",
                template: function (data) { return "" + ((data.IsFundable) ? 'true' : 'false') + ""; },
                title: "[resource_shortdisplayname[IsFundable]]",
                description: "[resource_description[IsFundable]]"
            },
            {
                field: "IsRaLine",
                type: "boolean",
                template: function (data) { return "" + ((data.IsRaLine) ? 'true' : 'false') + ""; },
                title: "[resource_shortdisplayname[IsRaLine]]",
                description: "[resource_description[IsRaLine]]"
            },
            {
                field: "AlsoPayOffer",
                type: "boolean",
                template: function (data) { return "" + ((data.AlsoPayOffer) ? 'true' : 'false') + ""; },
                title: "[resource_shortdisplayname[AlsoPayOffer]]",
                description: "[resource_description[AlsoPayOffer]]"
            },
            {
                field: "Description",
                title: "[resource_shortdisplayname[Description]]",
                description: "[resource_description[Description]]"
            },
            {
                field: "ProcessingState",
                title: "[resource_shortdisplayname[ProcessingState]]",
                description: "[resource_description[ProcessingState]]"
            },
            {
                field: "CreatedOn",
                type: "date",
                format: type.dateFormat,
                title: "[resource_shortdisplayname[CreatedOn]]",
                description: "[resource_description[CreatedOn]]"
            },
            {
                field: "ProcessedOn",
                type: "date",
                format: type.dateFormat,
                title: "[resource_shortdisplayname[ProcessedOn]]",
                description: "[resource_description[ProcessedOn]]"
            }
        ];

        var itemTemplate = $('[name=item-template]', container).html();
        var column = 0;
        var columnContainer = $(`[name=col-0]`, container);

        for(var field of fields) {
            if(splits.indexOf(field.field) !== -1) {
                column++;
                columnContainer = $(`[name=col-${column}]`, container);
            }

            console.log(field);
            if(typeof(field.type) == 'undefined') {
                // Nothing special to render.

                columnContainer.append(itemTemplate
                    .replace('{field}', field.field)
                    .replace('{value}', (transaction[field.field] || '&nbsp;'))
                    .replace('{description}', field.description));
            }
        }
    }
};
